sp_instance.widget_parameters:
{
	"html": {
		"value": "<style>
    .hod-dashboard-heading {
      text-align: center;
      padding: 24px 20px;
      background: linear-gradient(135deg, #e8f0fe 0%, #d4e2f7 100%);
      border-top-left-radius: 12px;
      border-top-right-radius: 12px;
      border: 1px solid #b8cfe8;
      box-shadow: 0 4px 16px rgba(26, 67, 113, 0.12);
      max-width: 100%;
      margin-top: 16px;
    }

    .hod-dashboard-heading h1 {
      font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
      font-size: 36px;
      font-weight: 700;
      color: #0b2a4a;
      margin: 0 0 8px 0;
      background: linear-gradient(145deg, #0b2a4a, #1a5276);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hod-dashboard-heading p {
      font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
      font-size: 16px;
      font-weight: 500;
      color: #1a3d5c;
      margin: 0;
      width: 100%;
      text-align: center;
      background: linear-gradient(135deg, #e8f0fe 0%, #d4e2f7 100%);
      display: inline-block;
      padding: 6px 24px;
      border-radius: 40px;
    }

    /* ServiceNow portal specific overrides */
    body {
      margin: 0;
      padding: 20px;
      background: #f0f5fb;
      font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    }

    /* Ensure compatibility with ServiceNow's default styles */
    .hod-dashboard-heading h1,
    .hod-dashboard-heading p {
      margin: 0;
      padding: 0;
    }

    .hod-dashboard-heading h1 {
      font-size: 32px;
      font-weight: 700;
      line-height: 1.2;
    }

    .hod-dashboard-heading p {
      font-size: 15px;
      font-weight: 500;
    }
  </style>
<div class="hod-dashboard-heading">
<h1>HOD Leave Dashboard</h1>
<p>Manage and review employee leave requests</p>
</div>",
		"displayValue": "<style>
